        private static void ByteToBase_stEPD(Array dst, byte[] src, int len = 1, int wordOffset = 0)
        {
            int[] indices = NewIndices(dst);
            int offset = wordOffset;
            for (int i = 0; i < len; i++)
            {
                stEPD elemTmp = new stEPD();
                NextIndices(dst, indices);
                ByteTo_stEPD(ref elemTmp, src, len, wordOffset);
                dst.SetValue(elemTmp, indices);
                wordOffset += stEPD_WSIZE;
            }
        }
